   12	// Day and Week are the units Parse adds to the standard library's.
   13	const (
   14		Day  = 24 * time.Hour
   15		Week = 7 * Day
   16	)
   17	
   18	var units = map[byte]time.Duration{
   19		's': time.Second,
   20		'm': time.Minute,
   21		'h': time.Hour,
   22		'd': Day,
   23		'w': Week,
   24	}
